import { readFileSync } from 'node:fs';

import { expect, it } from 'vitest';

import { emitTokens } from '../src/emit.ts';

const design: unknown = JSON.parse(
  readFileSync(new URL('../../../.impeccable/design.json', import.meta.url), 'utf8'),
);
const generated = (name: string) =>
  readFileSync(new URL(`../../../apps/web/styles/${name}`, import.meta.url), 'utf8');

// tokens.css, breakpoints.ts and tokens.ts are generated: edit design.json and run
// `pnpm tokens:build`, never the generated files.
it('committed generated files equal a fresh build', () => {
  const fresh = emitTokens(design);
  expect(generated('tokens.css')).toBe(fresh.css);
  expect(generated('breakpoints.ts')).toBe(fresh.breakpointsTs);
  expect(generated('tokens.ts')).toBe(fresh.tokensTs);
});

it('generated files carry the GENERATED header', () => {
  for (const name of ['tokens.css', 'breakpoints.ts', 'tokens.ts']) {
    expect(generated(name).split('\n')[0], name).toMatch(/GENERATED by packages\/design-tokens/);
  }
});
